import React, { useState } from "react";
import { CircularProgressbar, buildStyles } from "react-circular-progressbar";
import "react-circular-progressbar/dist/styles.css";

const Ahorro = () => {
  const [metaAhorro, setMetaAhorro] = useState(1000); // Meta de ahorro
  const [ahorroActual, setAhorroActual] = useState(0); // Cantidad de ahorro actual
  const [abono, setAbono] = useState(0); // Cantidad de abono
  const [frecuencia, setFrecuencia] = useState("semanal"); // Tipo de frecuencia de abono

  // Función para manejar el cambio en el input de abono
  const handleAbonoChange = (e) => {
    setAbono(parseFloat(e.target.value));
  };

  // Función para manejar el cambio en el selector de frecuencia
  const handleFrecuenciaChange = (e) => {
    setFrecuencia(e.target.value);
  };

  // Función para abonar al ahorro
  const handleAbonar = () => {
    setAhorroActual((prevAhorro) => {
      const nuevoAhorro = prevAhorro + abono;
      return nuevoAhorro > metaAhorro ? metaAhorro : nuevoAhorro;
    });
    setAbono(0); // Resetea el input de abono
  };

  // Calcular el porcentaje de progreso
  const porcentajeProgreso = (ahorroActual / metaAhorro) * 100;

  // Calcular el tiempo estimado para llegar a la meta
  const calcularTiempo = () => {
    const ahorroRestante = metaAhorro - ahorroActual;
    let diasEstimados = 0;

    if (frecuencia === "diario") {
      diasEstimados = ahorroRestante / abono;
    } else if (frecuencia === "semanal") {
      diasEstimados = (ahorroRestante / abono) * 7;
    } else if (frecuencia === "mensual") {
      diasEstimados = (ahorroRestante / abono) * 30;
    }

    return Math.ceil(diasEstimados); // Redondear hacia arriba
  };

  const diasEstimados = calcularTiempo();

  return (
    <div>
      <h2>Meta de Ahorro: ${metaAhorro}</h2>
      <h3>Ahorro Actual: ${ahorroActual}</h3>

      {/* Círculo de progreso */}
      <div style={{ width: 150, height: 150, margin: "20px auto" }}>
        <CircularProgressbar
          value={porcentajeProgreso}
          text={`${Math.round(porcentajeProgreso)}%`}
          styles={buildStyles({
            textColor: "#000",
            pathColor: "#3b82f6",
            trailColor: "#d6d6d6",
          })}
        />
      </div>

      {/* Input para abonar */}
      <div style={{ margin: "20px 0" }}>
        <input
          type="number"
          value={abono}
          onChange={handleAbonoChange}
          placeholder="Cantidad a abonar"
        />

        {/* Selector de frecuencia */}
        <select value={frecuencia} onChange={handleFrecuenciaChange}>
          <option value="diario">Diario</option>
          <option value="semanal">Semanal</option>
          <option value="mensual">Mensual</option>
        </select>
      </div>

      {/* Botón para abonar */}
      <button onClick={handleAbonar}>Abonar</button>

      {/* Tiempo estimado para llegar a la meta */}
      <h4>
        {diasEstimados > 0
          ? `Al ritmo actual (${frecuencia}), te tardarías ${diasEstimados} días en alcanzar la meta.`
          : "Introduce una cantidad para ver el tiempo estimado."}
      </h4>
    </div>
  );
};

export default Ahorro;


//npm install react-circular-progressbar
